<script setup lang="ts">
import AgentConsole from './components/AgentConsole.vue';
import {api, json} from './api/client';
import type {Bill,ImageRecord,OCRRun,Summary,Room,Trend,Exceptions} from './types';
import {ref,onMounted,nextTick} from 'vue';import * as echarts from 'echarts/core';import {LineChart} from 'echarts/charts';import {GridComponent,TooltipComponent} from 'echarts/components';import {CanvasRenderer} from 'echarts/renderers';echarts.use([LineChart,GridComponent,TooltipComponent,CanvasRenderer]);
const page=ref(new URLSearchParams(location.search).get('view')==='agent'?'业务分析':'概览'),stats=ref<Partial<Summary>>({}),rows=ref<Bill[]>([]),imgs=ref<ImageRecord[]>([]),rooms=ref<Room[]>([]),errors=ref<Exceptions>({bills:[],images:[]}),selected=ref<Bill|null>(null),history=ref<OCRRun[]>([]),labels=ref<Record<string,string>>({}),form=ref<Record<string,string>>({}),message=ref(''),chart=ref<HTMLDivElement>(),date=ref(new Date().toLocaleDateString('sv-SE')),query=ref(''),room=ref(''),start=ref(''),end=ref('');let graph: echarts.ECharts | undefined;
async function action(fn:()=>Promise<unknown>){try{message.value='';await fn()}catch(e){message.value=e instanceof Error?e.message:String(e)}}
const filters=()=>new URLSearchParams(Object.fromEntries(Object.entries({bill_no:query.value,room:room.value,start:start.value,end:end.value}).filter(([,v])=>v))).toString();
async function load(){[stats.value,rows.value,imgs.value,rooms.value,errors.value,labels.value]=await Promise.all([api<Summary>('/dashboard/summary?business_date='+date.value),api<Bill[]>('/bills?'+filters()),api<ImageRecord[]>('/images'),api<Room[]>('/dashboard/rooms'),api<Exceptions>('/dashboard/exceptions'),api<Record<string,string>>('/fields')]);if(page.value==='概览'){await nextTick();if(chart.value){graph?.dispose();graph=echarts.init(chart.value);const t=await api<Trend[]>('/dashboard/trend');graph.setOption({tooltip:{trigger:'axis'},grid:{left:65,right:25,bottom:35},xAxis:{type:'category',data:t.map(x=>x.date)},yAxis:{type:'value',name:'实收（元）'},series:[{type:'line',smooth:true,data:t.map(x=>x.received_amount/100),areaStyle:{color:'#dcece7'},itemStyle:{color:'#12725d'}}]})}}}
async function open(b:Bill){selected.value=await api<Bill>('/bills/'+b.id);history.value=await api<OCRRun[]>('/images/'+b.image_id+'/ocr-runs');form.value=Object.fromEntries(Object.keys(labels.value).map(k=>[k,b[k]==null?'':k.endsWith('_amount')?String(Number(b[k])/100):String(b[k])]));page.value='详情'}
async function save(){if(!selected.value)return;await api('/bills/'+selected.value.id+'/fields',json('PATCH',{fields:Object.fromEntries(Object.entries(form.value).map(([k,v])=>[k,v===''?null:v]))}));message.value='已保存，原始 OCR 保留';await open(await api<Bill>('/bills/'+selected.value.id))}
async function review(){if(!selected.value)return;await api('/bills/'+selected.value.id+'/review',json('POST',{confirm_all:true,acknowledge_issues:true}));message.value='已复核';await load()}
async function upload(e:Event){const input=e.target as HTMLInputElement;const files=Array.from(input.files||[]);if(!files.length)return;const b=await api<{id:string}>('/batches',json('POST',{business_date:date.value}));for(const f of files){const body=new FormData();body.append('file',f);body.append('business_date',date.value);body.append('batch_id',b.id);const result=await api<{status:string}>('/uploads',{method:'POST',body});message.value=f.name+'：'+result.status}await load()}
async function backup(){const r=await api<{filename:string;download_url:string}>('/backups',{method:'POST'});await api('/backups/verify',json('POST',{filename:r.filename}));location.href=r.download_url}
onMounted(()=>action(load));
</script>
<template><aside><div class="brand">KTV <small>账单工作台</small></div><p class="muted">本地数据 · 可追溯管理</p><nav><button v-for="p in ['概览','账单','上传记录','房间统计','异常','业务分析','设置']" :class="{active:page===p}" @click="page=p;action(load)">{{p}}</button></nav><footer>方案 V1.2<br>仅统计已复核、已结且无重复账单</footer></aside><main><header><div><p class="eyebrow">营业数据 / {{page}}</p><h1>{{page==='概览'?'每日经营，一目了然':page}}</h1></div><label>归档日期 <input type="date" v-model="date" @change="action(load)"></label></header><p v-if="message" class="notice" role="status">{{message}}</p>
<template v-if="page==='概览'"><div class="cards"><article v-for="[k,l] in [['received_amount','今日实收（元）'],['settled','今日有效账单'],['pending','待复核'],['duplicates','疑似重复']]" :key="k"><p>{{l}}</p><strong>{{k==='received_amount'?(Number(stats[k]||0)/100).toFixed(2):stats[k]||0}}</strong></article></div><section><h2>实收金额趋势</h2><p class="muted">{{stats.scope}} · 当前累计 {{stats.total_bills||0}} 条样本</p><div ref="chart" class="chart"></div></section><section><h2>开始采集</h2><p>上传账单后自动进入本地 OCR 队列；请在账单详情中核对字段。</p><input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="e=>action(()=>upload(e))"></section></template>
<template v-if="page==='账单'"><section class="toolbar"><input placeholder="搜索账单编号" v-model="query"><input placeholder="房间名称" v-model="room"><input type="date" v-model="start"><input type="date" v-model="end"><button @click="action(load)">筛选</button><a :href="'/api/v1/exports/bills?format=xlsx&'+filters()">导出 Excel</a><a :href="'/api/v1/exports/bills?format=csv&'+filters()">CSV</a></section><section><table><thead><tr><th>账单编号</th><th>房间</th><th>账单日期</th><th>实收（元）</th><th>复核 / 重复</th><th></th></tr></thead><tbody><tr v-for="b in rows"><td>{{b.bill_no||'待补充'}}</td><td>{{b.room_name||'—'}}</td><td>{{b.bill_date||'—'}}</td><td>{{b.received_amount==null?'—':(b.received_amount/100).toFixed(2)}}</td><td>{{b.review_status}} / {{b.duplicate_status}}</td><td><button @click="action(()=>open(b))">核对</button></td></tr></tbody></table><p v-if="!rows.length">暂无符合条件的账单。</p></section></template>
<section v-if="page==='上传记录'"><input type="file" multiple accept="image/*" @change="e=>action(()=>upload(e))"><button @click="action(load)">刷新状态</button><article class="record" v-for="i in imgs"><img :src="'/api/v1/images/'+i.id+'/file?thumbnail=true'"><div><b>{{i.original_name}}</b><p>{{i.business_date}} · {{i.status}}</p><p>{{i.error_message}}</p><button @click="action(async()=>{await api('/images/'+i.id+'/recognize',{method:'POST'});await load()})">重新识别</button><button v-if="i.bill_id" @click="action(async()=>open(await api('/bills/'+i.bill_id)))">账单详情</button></div></article><p v-if="!imgs.length">还没有上传图片。</p></section>
<section v-if="page==='房间统计'"><h2>已复核有效账单样本</h2><table><tr><th>房间</th><th>账单数</th><th>实收（元）</th><th>消费分钟</th></tr><tr v-for="r in rooms"><td>{{r.room}}</td><td>{{r.count}}</td><td>{{r.received_amount/100}}</td><td>{{r.duration_minutes}}</td></tr></table></section>
<section v-if="page==='异常'"><h2>待复核与疑似重复</h2><article v-for="b in errors.bills"><button @click="action(()=>open(b))">{{b.bill_no||b.id}} · {{b.duplicate_status}}</button><p>{{b.issues_json}}</p></article><h2>识别失败</h2><p v-for="i in errors.images">{{i.original_name}}：{{i.error_message}}</p></section>
<div v-if="page==='详情'&&selected" class="detail"><section><a :href="'/api/v1/images/'+selected.image_id+'/file'" target="_blank"><img class="receipt" :src="'/api/v1/images/'+selected.image_id+'/file'"></a><h2>OCR 历史</h2><details v-for="h in history"><summary>{{h.started_at}} · {{h.status}} · {{h.engine_version}}</summary><pre>{{h.raw_text||h.error_message}}</pre></details><h2>修改历史</h2><p v-for="l in selected.edit_logs">{{l.field_key}}：{{l.old_value}} → {{l.new_value}}</p></section><section><h2>核对字段</h2><p class="muted">金额单位：元。清空后保存会明确记录为空；复核表示已确认所有字段及异常。</p><p class="notice">{{selected.issues.join('；')||'未发现业务异常'}}</p><label class="field" v-for="(l,k) in labels">{{l.split('|')[0]}}<input v-model="form[k]"></label><button @click="action(save)">保存修正</button><button @click="action(review)">确认字段和异常并复核</button></section></div>
<AgentConsole v-if="page==='业务分析'" @open-bill="id=>action(async()=>open(await api<Bill>('/bills/'+id)))" /><section v-if="page==='设置'"><h2>完整备份</h2><p>生成数据库一致性快照，并包含原图、处理图、缩略图和哈希清单。</p><button @click="action(backup)">创建、校验并下载备份</button><h2>本地运行</h2><p>恢复前关闭后端，使用项目恢复脚本。OCR 首次运行需要下载模型。</p></section>
</main></template>
